import * as E from './engine.js';
import {buildHints} from './build-hints.js';
import {tile} from './tiles.js';
import {renderPatternGuide,renderPatternResults} from './pattern-guide.js';
import {buildSettlementSnapshot,createSettlementPlayer} from './settlement-adapter.js';
import {captureGameState,trackGameAction} from './analytics/game-adapter.js';
import {ARTWORK,artUrl,initArtAssets,preloadRemainingArt} from './art-loader.js';

const app=document.querySelector('#app'),wrap=document.querySelector('#settlement-wrap'),SAVE='jade-run-v8',PREF='jade-run-sound',mode='mcr';
let game=null,legacy=false,hiddenRiichiSave=null;
try{legacy=[7,6,5,4,3,2,1].some(version=>localStorage.getItem(`jade-run-v${version}`));const raw=localStorage.getItem(SAVE),saved=raw?JSON.parse(raw):null;if(saved?.mode==='riichi')hiddenRiichiSave={raw,runId:saved.runId||'legacy'};else game=E.restore(raw);}catch{}
let screen='home',selected=[],formedSelected=[],dialog=null,sound=false,notificationTimer,player=null,speed=1,skipped=false,inputMethod='pointer';
let guideFilter='all',guideQuery='',buildExpanded=false,lastBuildKey='',lastActiveIds=new Set();
const shapeName=shape=>({normal:'四组面子＋一对雀头',pairs:'七对',orphans:'十三幺结构',knitted:'组合龙',unconnected:'不靠牌形'})[shape]||'完整牌形';
let reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
try{sound=localStorage.getItem(PREF)==='true';}catch{}
const fmt=n=>new Intl.NumberFormat('zh-CN',{maximumFractionDigits:6}).format(n??0);
const signed=n=>(n>=0?'+':'')+fmt(n);
const gainLabel=x=>x.kind==='base'?'+'+fmt(x.value)+' 底分':x.kind==='addMult'?'+'+fmt(x.value)+' 倍率':x.kind==='retrigger'?'额外 '+fmt(x.value)+' 次':x.kind==='unlock'?'解锁番型':x.kind==='core'?'牌型 ×'+fmt(x.value):'×'+fmt(x.value);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(act,text,cls='',attrs='')=>`<button class="${cls}" data-act="${act}" ${attrs}>${text}</button>`;
const artwork=ARTWORK;
let backgroundArtStarted=false,booting=true;
function applyArtStyles(){
 for(const key of ['page','board','shop']){const src=artwork.backgrounds?.[key];if(typeof src==='string'&&/^\.\/art\/[a-zA-Z0-9_./-]+$/.test(src))document.documentElement.style.setProperty('--art-'+key,`url("${artUrl(src)}")`);}
 let fonts=document.querySelector('#art-font-sources');if(!fonts){fonts=document.createElement('style');fonts.id='art-font-sources';document.head.append(fonts);}
 const src=artUrl('./settlement/cinematic/MaShanZheng-subset.woff2');
 fonts.textContent=['ShanBrush','BurstBrush'].map(name=>`@font-face{font-family:${name};src:url("${src}") format("woff2");font-display:swap}`).join('');
}
function prepareBackgroundArt(){if(screen!=='game'||backgroundArtStarted)return;backgroundArtStarted=true;preloadRemainingArt().then(applyArtStyles).catch(()=>{});}
function persist(){try{localStorage.setItem(SAVE,JSON.stringify(game));}catch{toast('无法保存进度，本次游戏仍可继续。');}}
function toast(msg){clearTimeout(notificationTimer);const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');notificationTimer=setTimeout(()=>el.classList.remove('show'),3600);}
const capture=()=>{try{return captureGameState(game);}catch{return null;}};
function track(action,before,result,context={}){try{Promise.resolve(trackGameAction(action,before,game,result,{input_method:inputMethod,...context})).catch(()=>{});}catch{}}
const chosen=()=>[...selected,...formedSelected];
const preparing=()=>game?.phase==='prepare';
const editing=()=>preparing();
const editsLeft=()=>preparing()?Math.max(0,Math.floor((game?.ink||0)/E.BALANCE.editCost)):0;
const ownsEditTool=()=>['rank_brush','suit_ribbon','core_high'].some(id=>game?.relics.includes(id));
const canRescue=()=>game?.relics.includes('core_high')&&game.relics.includes('high_rescue')&&!game.rescueUsed&&(preparing()||game.phase==='play'&&E.structuralCount(game)<14);
const canExchange=()=>['prepare','play'].includes(game?.phase)&&selected.length>0&&selected.length<=E.BALANCE.openingExchangeSize&&!formedSelected.length&&game.swaps>0&&game.deck.length>=selected.length;
const locked=()=>new Set(game.kongs.flatMap(k=>k.tileIds));
const canDiscardFormed=()=>game?.phase==='play'&&!game.formedDiscard&&!selected.length&&formedSelected.length>=1&&formedSelected.length<=2&&formedSelected.every(id=>game.formed.some(t=>t.id===id)&&!locked().has(id));
const selectedEditTile=()=>preparing()&&selected.length===1&&!formedSelected.length?game.hand.find(t=>t.id===selected[0]&&t.face<27):null;
const repairAdvice=()=>{const advice=[];if(game?.phase==='play'&&!game.formedDiscard)advice.push('本趟还可弃除成型牌一次，最多2张，弃后不立即补摸');if(game?.swaps>0&&E.structuralCount(game)<14)advice.push(`还可弃换候选 ${game.swaps} 次，再用新牌补齐`);if(canRescue()&&!preparing())advice.push('尚有一次大番补缺弃换机会');return '准备已结束，不能再改点、换色或制作万能牌。'+(advice.length?advice.join('；')+'。需自行选择操作，不保证修复成功。':'最终未和牌会诈胡，扣除本关门槛的10%。');};
function clear(){selected=[];formedSelected=[];}
function mutate(action,fn,context={},message=''){const before=capture();const result=fn();track(action,before,result,context);if(result===false||result?.valid===false||result?.ok===false){toast(result?.reason||'当前无法执行，请检查选择和剩余资源。');return false;}clear();dialog=null;persist();render();if(message)toast(typeof message==='function'?message(result):message);return true;}
function emblem(id,showcase=false){const r=E.relic(id),src=artwork.relics?.[id];return `<span class="relic-emblem${showcase?' relic-showcase':''}" data-art="${id}"><span>${r.icon}</span>${typeof src==='string'&&/^\.\/art\//.test(src)?`<img src="${esc(artUrl(src))}" alt="${showcase?esc(r.name)+'奇物原画':''}" loading="${showcase?'eager':'lazy'}" width="256" height="256">`:''}</span>`;}
function header(){return `<header class="topbar"><a href="#" data-act="home" class="brand"><span class="brand-tile">雀</span><span>叠雀<small>MAHJONG · ROGUELIKE</small></span></a><div class="top-actions"><span class="edition">四途构筑 <i>V8</i></span>${button('sound',sound?'♪ 声音开':'♪ 声音关','text-btn')}${button('patterns','番型图鉴 ↗','text-btn')}${button('rules','玩法说明','text-btn')}</div></header>`;}
function home(){const resumable=game?.mode===mode&&!['victory','defeat'].includes(game.phase);return `<main class="home"><div class="home-intro"><div class="eyebrow"><span class="mini-line"></span> 一场关于组合与奇遇的牌局</div><h1>一张，也能<br>叠出<span>青山。</span></h1><p class="home-copy">自由出牌，落成十四张。<br>用奇物改写牌面，让番型与倍率一起生长。</p><div class="home-facts"><span>六重山境</span><span>四条计分路线</span><span>累计得分闯关</span></div><div class="fan-art" aria-hidden="true"><span class="fan-orbit"></span>${[0,9,18,32,4].map((t,i)=>`<div style="--i:${i}">${tile(t)}</div>`).join('')}<span class="art-seal">好牌<br>成双</span></div></div><section class="mode-panel"><div class="section-kicker">国标启程</div><h2>以番型与奇物，叠出高分。</h2><div class="mode-card active"><span class="mode-symbol">国</span><span><strong>${E.MODES[mode].name}</strong><small>番型相叠，百般成局</small></span></div><div class="freeplay-intro">12 张候选，出几张补几张，其他牌留在手边。准备与组牌共用 ${E.BALANCE.openingExchanges} 次弃换；自带升降笔，仅准备时可改牌 1 次；整趟可弃除成型牌 1 次，最多 2 张。</div><p class="scope-note">${E.BASE_PATTERNS[mode].length} 项基础番型 · 肉鸽计分 · 奇物解锁扩展</p>${button('start','开始新的旅程 <span>→</span>','primary wide')}${resumable?button('continue',`继续上次 · ${E.MODES[game.mode].short} · 第 ${game.round+1} 关`,'secondary wide'):''}<div class="save-note"><span class="live-dot"></span> 进度自动保存在当前浏览器</div>${hiddenRiichiSave?'<p class="legacy-note">日麻入口暂时关闭，原进度仍保留；开始国标旅程时将先另存备份。</p>':''}${legacy?'<p class="legacy-note">V7 及更早版本的进度与成绩仍保留。V8 使用新规则，旧局需另开旅程，不会覆盖旧版存档。</p>':''}</section></main><footer class="home-footer"><span>以牌为径，以奇物为伴。</span><span>单人构筑 · 无需注册</span></footer>`;}
function relicCard(id,act='',extra=''){const r=E.relic(id);return `<article class="relic-card ${r.kind==='秘卷'?'rare':''}"><div class="relic-card-top"><span class="tag">${r.kind}</span>${emblem(id,true)}</div><div class="relic-card-copy"><h3>${r.name}</h3><p>${r.desc}</p></div>${act?button(act,extra||'收入囊中 →','secondary wide',`data-id="${id}"`):''}</article>`;}
function runPath(){return `<nav class="run-path" aria-label="关卡进度">${E.ROUND_NAMES.map((n,i)=>`<div class="path-node ${i===game.round?'current':''} ${i<game.round?'done':''}"><span>${i<game.round?'✓':i===2||i===5?'◆':String(i+1).padStart(2,'0')}</span><small>${n}</small></div>`).join('')}</nav>`;}
function stats(){const target=E.target(game),pct=Math.max(0,Math.min(100,game.totalScore/target*100));return `<aside class="score-column"><section class="score-card"><div class="eyebrow">旅程累计 <span class="tag">${E.MODES[game.mode].short}</span></div><div class="score-number">${fmt(game.totalScore)}</div><div class="target-line">本关门槛 <strong>${fmt(target)}</strong><span>${Math.floor(pct)}%</span></div><div class="progress-track"><i style="width:${pct}%"></i></div><p>${game.totalScore>=target?'累计已达标，仍需完成本关结算':'距门槛还差 '+fmt(target-game.totalScore)+' 分'}</p><p class="carry-note">入关 ${fmt(game.roundStartScore)} · 过程 ${signed(game.processScore)}</p></section><div class="resources">${[['↻','本关弃换 · 共用次数',game.swaps],['墨',preparing()?`准备改牌 · ${E.BALANCE.editCost} 墨/次`:'改牌 · 准备已结束',editsLeft()+' 次'],['◉','铜钱',game.coins],['▤','剩余牌山',game.deck.length]].map(([icon,name,n])=>`<div><span class="resource-icon">${icon}</span><span>${name}</span><strong>${n}</strong></div>`).join('')}</div><div class="round-note"><span>${preparing()?'准备阶段':'组牌阶段'}</span><p>${preparing()?'改牌仅限准备。准备结束后不可改点、换色或制作万能牌；剩余弃换次数可留到组牌中使用。':game.round===5?'绝顶寒风：本关和牌分 ×0.8。':'改牌已关闭；可继续弃换候选。分数跨关累计，每关只结算一次。'}</p></div>${button('retire','结束本次挑战','text-btn retire')}</aside>`;}
function warning(info){if(preparing())return `<div class="shape-warning safe"><b>先准备，再落牌</b><span>选择候选牌弃换，或用升降笔改点。改牌只在准备时开放；剩余弃换次数可留到组牌时使用。</span></div>`;return `<div class="shape-warning ${info.risk==='needs_repair'||info.complete&&!info.legal?'critical':'safe'}" role="status"><b>${info.complete?(info.legal?'牌形成立':'尚未和牌'):info.risk==='needs_repair'?'牌形风险':'成型进度'}</b><span>${esc(info.reason)}</span>${info.risk==='needs_repair'?`<small>${repairAdvice()}</small>`:''}</div>`;}
function board(){const lock=locked(),info=E.inspect(game);return `<section class="table-area"><div class="table-title"><span>成型区 <small>${E.structuralCount(game)} / 14 位置${game.kongs.length?' · '+game.formed.length+' 张实体牌':''}</small></span>${button('log','计分记录 ↗','text-btn')}</div>${warning(info)}<div class="formed-rack">${game.formed.filter(t=>!lock.has(t.id)).sort((a,b)=>a.face-b.face||Number(a.wild)-Number(b.wild)||a.id.localeCompare(b.id)).map(t=>tile(t,{size:'small',zone:'formed',selected:formedSelected.includes(t.id)})).join('')||(game.kongs.length?'':'<div class="formation-empty"><span>叠 雀</span><p>从备选区出牌，逐步组成这一手。</p></div>')}</div>${game.kongs.length?`<div class="kong-row">${[...game.kongs].sort((a,b)=>a.face-b.face||a.id.localeCompare(b.id)).map(k=>`<div class="kong-group">${k.tileIds.map(id=>tile(game.formed.find(t=>t.id===id),{size:'small',locked:true})).join('')}<small>已声明杠 · 3 位置</small></div>`).join('')}</div>`:''}<div class="hand-toolbar"><span class="muted">${formedSelected.length?'已选 '+formedSelected.length+' 张成型牌':'成型区按花色与点数排序 · 可选牌弃除'}</span></div><div class="free-actions">${button('formed-discard',game.formedDiscard?'成型弃除 · 本趟已用':'弃除选中成型牌 · 整趟1次','secondary',canDiscardFormed()?'':'disabled')}<small>${game.formedDiscard?'第 '+(game.formedDiscard.round+1)+' 关已使用，后续关卡不恢复。':'一次弃1～2张，不立即补摸；可在满14张、尚未结算时使用。'}</small></div></section>`;}
function hand(){const prep=preparing(),info=prep?{valid:false}:E.inspect(game,selected),canCommit=!prep&&selected.length&&!formedSelected.length&&info.valid,rescue=canRescue(),exchangeButton=button('exchange',`↻ 弃换选中牌 · 余${game.swaps}次`,'secondary',canExchange()?'':'disabled');return `<section class="hand-section"><div class="hand-toolbar"><div><strong>${prep?'起手准备':'候选牌'} · ${game.hand.length} 张</strong><span>已选 ${selected.length} 张 · 已摸 ${136-game.deck.length}/136</span></div>${button('clear','取消选择','text-btn',chosen().length?'':'disabled')}</div><p class="batch-note">${prep?`仅准备时可改牌，还可改 ${editsLeft()} 次。`:'出几张补几张，其余候选保留；改牌已关闭。'}本关还可弃换 ${game.swaps} 次，每次 1～${E.BALANCE.openingExchangeSize} 张，准备与组牌共用。</p><div class="tile-rack">${game.hand.map(t=>tile(t,{zone:'hand',selected:selected.includes(t.id)})).join('')}</div>${!prep&&selected.length&&!formedSelected.length?`<div class="selection-warning ${info.risk==='needs_repair'?'critical':''}">出牌后：${esc(info.reason)}</div>`:''}<div class="hand-help">${chosen().length?chosen().map(id=>E.tileName([...game.hand,...game.formed].find(t=>t.id===id))).join(' · '):prep?'留下想要的组合，选中不需要的牌再弃换。':'单张、多张均可放入成型区；杠＝四张相同牌，声明后占三个位置。'}</div><div class="free-actions">${prep?`${button('transform',`✎ 准备改牌 · 余 ${editsLeft()} 次`,'secondary',selectedEditTile()&&editsLeft()&&ownsEditTool()?'':'disabled')}${exchangeButton}${button('begin-play','准备好了 · 开始组牌 →','primary begin-play')}`:`${exchangeButton}${button('kong','声明杠 · 四张相同','secondary',chosen().length===4?'':'disabled')}${button('commit',selected.length?'放入 '+selected.length+' · 补 '+Math.min(selected.length,game.deck.length)+' →':'出选中牌 →','primary',canCommit?'':'disabled')}`}</div>${game.relics.includes('high_rescue')?`<div class="rescue-panel"><div><b>大番补缺</b><small>${game.rescueUsed?'本关补缺已使用。':prep?'准备时可花共用改牌额度编辑1张；也可留到组牌时弃换最多3张，整关二选一。':rescue?'组牌时可弃换最多3张；已不能改点或换色。':'满14张后无法补缺；需同时装备大番核心。'}</small></div><div class="free-actions">${prep?button('rescue-transform','补缺 · 准备改1张','secondary',rescue&&selectedEditTile()&&editsLeft()?'':'disabled'):button('rescue-exchange','补缺 · 弃换选中牌','secondary',rescue&&selected.length>0&&selected.length<=E.BALANCE.highRescueSize&&!formedSelected.length&&game.deck.length>=selected.length?'':'disabled')}</div></div>`:''}</section>`;}

function buildHintRow(row,fresh=false){
 const labels={active:'已触发',progress:'积累中',support:'辅助',inactive:'未触发'},detail=row.state==='active'?row.detail.replace('已计入当前最佳解释。',''):row.detail;
 return `<article class="build-hint ${row.state==='active'?'is-active':''} ${fresh?'synergy-new':''}" data-build-relic="${esc(row.id)}"><button class="build-hint-title" data-act="relic" data-id="${esc(row.id)}">${emblem(row.id)}<span><b>${esc(row.name)}</b><small>${labels[row.state]||'构筑'}</small></span><strong>${esc(row.effect)}</strong></button>${row.state!=='active'?`<p class="build-progress">${esc(row.progress)}</p>`:''}${detail?`<p class="build-detail">${esc(detail)}</p>`:''}</article>`;
}
function buildPanel(hints){
 const priority=['wheel','mountain','jiang','echo','pair','kong_cauldron'];
 const rows=[...hints.rows].sort((a,b)=>{const rank=x=>x.state==='active'?-20:x.state==='support'?30:priority.includes(x.id)?priority.indexOf(x.id):15;return rank(a)-rank(b);});
 const shown=buildExpanded?rows:rows.slice(0,4),fresh=new Set(hints.justActive||[]);
 const heading=hints.legal?'本手联动已核算':hints.legal===false?'先修复牌形，再触发联动':hints.complete?'等待结算验证':'让奇物一起成势';
 return `<section class="build-panel" aria-label="构筑联动"><div class="build-heading"><span class="section-kicker">构筑联动</span><span class="build-count">${hints.legal?hints.activeIds.length+' 件已触发':'按成型区统计'}</span></div><h3>${heading}</h3><p class="build-caption">${hints.legal?'依据本手最高分解释，收益已计入终局试算。':hints.legal===false?'当前无法和牌，终局计分奇物暂不生效。':hints.complete?'结算预览暂不可用，尚未确认联动。':'目标进度不保证后续摸到所需牌；和牌后统一计分。'}</p><div class="build-hints">${shown.map(row=>buildHintRow(row,fresh.has(row.id))).join('')||'<p class="build-empty">收集奇物，选择这一局想做的组合。</p>'}</div>${rows.length>4?button('build-details',buildExpanded?'收起更多奇物 ↑':'查看其余 '+(rows.length-4)+' 件奇物 ↓','text-btn build-more'):''}</section>`;
}

function previewPanel(p,hints){return `<aside class="preview-column"><section class="preview-card"><div class="eyebrow">终局试算 <span class="preview-dot"></span></div><div class="preview-number">${p.valid?signed(p.delta):'—'}</div>${p.valid&&p.legal?`<div class="formula"><span><strong>${fmt(p.base)}</strong>底分</span><b>×</b><span><strong>${fmt(p.mult)}</strong>倍率</span></div>`:''}<div class="score-detail">${p.valid?`${p.legal?`<span class="finish-tag">${shapeName(p.decomposition.shape)} · ${p.fans} ${E.MODES[game.mode].unit}</span>${p.patterns.map(x=>`<div><span>${x.name}</span><b>+${x.fan}${E.MODES[game.mode].unit}</b></div>`).join('')}${p.gains.map(x=>`<div class="${x.kind==='unlock'?'unlock-line':''}"><span>${x.name}</span><b>${gainLabel(x)}</b></div>`).join('')}`:`<p class="critical">当前牌形无法和牌。结算将诈胡，扣除 ${fmt(p.penalty)} 分。</p>`}<div class="cumulative-preview"><span>结算后累计</span><strong>${fmt(p.cumulativeAfter)}</strong><small>${p.passed?'达到门槛，可以过关':'未达 '+fmt(p.target)+'，本次旅程将结束'}</small></div>`:`<p>${esc(p.reason)}。${preparing()?'先完成开局准备，再开始组牌。':'继续出牌形成完整牌型；已入成型区的牌不能替换。'}</p>`}</div>${button('settle',p.valid&&!p.legal?'诈胡结算 →':'和牌并结算 →',`primary wide ${p.valid&&!p.legal?'danger-btn':''}`,p.valid?'':'disabled')}<small class="keyboard-hint">每关一次终局结算 · 预览不会消耗资源</small></section></aside>`;}
function relicDock(hints){const active=new Set(hints?.activeIds||[]),fresh=new Set(hints?.justActive||[]);return `<section class="relic-dock"><div class="dock-title"><div class="section-kicker">随行奇物 <span>${game.relics.length} / 4 件 · 最多1核心${active.size?' · 本手触发 '+active.size+' 件':''}</span></div><span>点击查看效果</span></div><div class="relic-list">${game.relics.map(id=>`<button data-act="relic" data-id="${id}" class="relic-chip ${E.relic(id).kind==='秘卷'?'rare':''} ${active.has(id)?'synergy-active':''} ${fresh.has(id)?'synergy-new':''}">${emblem(id)}<span>${E.relic(id).name}<small>${active.has(id)?'本手已触发':E.relic(id).kind}</small></span></button>`).join('')}</div></section>`;}
function play(){
 const preview=E.currentSettlementPreview(game),hints=buildHints(game,preview),key=game.roundId;
 hints.justActive=key===lastBuildKey?hints.activeIds.filter(id=>!lastActiveIds.has(id)):[];
 lastBuildKey=key;lastActiveIds=new Set(hints.activeIds);
 return `<main class="game-shell">${runPath()}<div class="game-heading"><div><span class="section-kicker">第 ${String(game.round+1).padStart(2,'0')} 关 / 六重山境</span><h1>${E.ROUND_NAMES[game.round]}</h1></div><span class="tag">${preparing()?'开局准备':'组牌中'} · 自动择优计分</span></div><div class="play-layout">${stats()}<div class="center-column">${board()}${hand()}${buildPanel(hints)}</div>${previewPanel(preview,hints)}</div>${relicDock(hints)}</main>`;
}
function finalSummary(){const p=game.last;return p?`<div class="final-summary settlement-summary"><div><span>${p.legal?'和牌得分':'诈胡扣分'}</span><strong>${signed(p.delta)}</strong></div><p>${p.legal?p.patterns.map(x=>x.name+' '+x.fan+E.MODES[game.mode].unit).join(' · ')||'基础和牌':'本手未和牌，不获得和牌奖励。'}</p><div><span>累计 ${fmt(p.cumulativeBefore)} → ${fmt(p.cumulativeAfter)}</span><b>${p.passed?'累计达标 · 过关':'累计未达标 · 止步'}</b></div><p>本关门槛 ${fmt(p.target)} · 过程分已计入累计，不重复加分</p></div>`:'';}
function selectionScene(starter=false){return `<main class="choice-scene"><div class="scene-heading"><div class="eyebrow">${starter?'旅程开始 · '+E.MODES[game.mode].name:'第 '+(game.round+1)+' 关已通过'}</div><h1>${starter?'四条路径，选一条启程。':'给你的构筑，添一件奇物。'}</h1><p>${starter?'每局只装备一个计分核心，并自带升降笔。高番、刻子、留牌、成长，都能叠出大数字。':'本关仅能选择一件；满4槽时，需要替换一件已有奇物。'}</p></div>${starter?'':finalSummary()}<div class="choice-grid ${starter?'starter-grid':''}">${game.offers.map(id=>relicCard(id,starter?'starter':'reward',starter?'以此启程 →':game.relics.length>=4?'选择并替换 →':'收入囊中 →')).join('')}</div><p class="choice-note">${starter?'共4个装备位，核心与升降笔开局共占2格；仅准备时可改牌1次。其余奇物在过关后逐步获得。':'计分核心与辅助共同占用4格，本关内不能换装。'}</p>${starter?'':button('skip-reward','跳过本次奇遇','text-btn skip-reward')}</main>`;}
function shop(){return `<main class="shop-scene"><div class="scene-heading"><div class="eyebrow">关间整备</div><h1>带上新的可能。</h1><p>累计 ${fmt(game.totalScore)} 分，将带入下一关。本关奇物选择已结束。</p></div>${relicDock()}<div class="shop-next"><div><span class="section-kicker">下一关 · ${E.ROUND_NAMES[game.round+1]}</span><p>累计门槛 ${fmt(E.TARGETS[game.mode][game.round+1])}</p></div>${button('next','继续上山 →','primary')}</div></main>`;}
function ending(){const win=game.phase==='victory';return `<main class="end-scene"><div class="end-seal">${win?'登顶':'再会'}</div><div class="eyebrow">${E.MODES[game.mode].name} · ${win?'六境皆过':'旅程暂歇'}</div><h1>${win?'山高，仍有好牌。':'再叠一手，便是新局。'}</h1><p>${win?'这一程的番型与奇物，组成了你的答案。':`止步于「${E.ROUND_NAMES[game.round]}」，下次奇遇会带来新的方向。`}</p><div class="end-stats"><div><strong>${fmt(game.totalScore)}</strong><span>旅程累计</span></div><div><strong>${fmt(game.bestHand)}</strong><span>最高和牌分</span></div><div><strong>${win?6:game.round} / 6</strong><span>通过关卡</span></div></div>${finalSummary()}${relicDock()}<div class="end-actions">${button('home','返回首页','secondary')}${button('restart','国标再来一局 →','primary')}</div></main>`;}
function settlementScene(){return `<main class="choice-scene"><div class="scene-heading"><div class="eyebrow">第 ${game.round+1} 关 · 结算已保存</div><h1>这一手，落定。</h1><p>重播或刷新不会重复计分。</p></div>${finalSummary()}<div class="end-actions">${button('replay','重播结算','secondary')}${button('settlement-continue','继续 →','primary')}</div></main>`;}
function rules(){const b=E.BALANCE,base=value=>fmt(value*b.baseScale);return `<div class="rule-intro">四途构筑 · 国标 · V8</div><h2>准备改牌，组牌也能弃换。</h2><h3>先认识牌与组合</h3><p>数牌是万、筒、索（条）的1～9；字牌是东、南、西、北、中、发、白。顺子是三张同花色且点数连续的数牌，如二三四万；刻子是三张相同牌，如三个东；杠是四张相同牌。对子是两张相同牌，在普通和牌中作为雀头。面子指一组顺子、刻子或杠；普通和牌由四组面子和一对雀头组成。七对等特殊牌型另算。</p><p>幺九牌指一、九数牌和所有字牌；老头牌只指一、九数牌，不含字牌。字牌不能组成顺子。“和牌”就是牌形成立，本作按14个结构位置判断，杠的第四张不多占位置。</p><ol class="rule-steps"><li><b>选择核心。</b>高番、刻子、留牌、成长四选一，同时带上升降笔，开局共占2槽。最多装备${b.relicSlots}件奇物，只能有1件核心。</li><li><b>准备与弃换。</b>136张牌，起手${b.handSize}张候选；每关${b.openingExchanges}次弃换，每次1～${b.openingExchangeSize}张。准备和组牌共用这些次数，开始组牌不补回也不清零。满14张、尚未结算时仍可弃换候选，影响留牌收益，但不会改动成型牌。</li><li><b>仅准备时改牌。</b>每关${b.ink}墨，每次消耗${b.editCost}墨。选一张候选数牌，用升降笔改点±1、换色绫换花色；天机算筹自带花色万能，保留点数，仅可变万／筒／索，不代字牌。须持有对应工具或核心，三种改法共用一次额度。点击“开始组牌”后全部关闭，未用额度不延后。</li><li><b>自由组牌。</b>出几张补几张，其余候选保留。整趟可在组牌时弃除成型牌一次，选1～2张非杠牌，永久移入弃牌区，不立即补摸。只弃1张也消耗整次机会；下一关不恢复。最终组成合法和牌，系统取奇物联动后的最高分解释。</li><li><b>大番补缺。</b>同时装备天机算筹与补缺符，每关二选一：准备时花共用${b.editCost}墨改点±1／花色，或在组牌且未满14张时额外弃换最多${b.highRescueSize}张。补缺不赠送改牌次数，也不能在组牌中改牌。</li><li><b>声明杠。</b>四张相同有效牌可跨两区声明杠。杠锁定后占3个结构位置，不可弃除，每杠使最终实体牌多1张。</li><li><b>结算闯关。</b>每关一次结算，分数跨关累计，不扣除门槛。诈胡指最终牌形不成立却结算，扣本关门槛10%（向上取整），扣后仍达标也能过关。过关选1件奇物，满槽替换或跳过。</li></ol><div class="rule-callout">番是牌型的计分单位。普通牌型倍率：1＋总番÷8；大番核心改用阶梯倍率。刻子路线靠面子触发连乘，留牌路线按结算时仍在候选区的幺九牌计分，成长路线累计顺子收益。完整和牌底分＝数牌每张${base(b.tileBase)}、字牌${base(b.honorBase)}，再加${base(b.completeBase)}。最后补来的候选计入留牌收益，不能加入已经填满的和牌。</div><h3>触发与成长</h3><p>重触发指让同一组牌的计分效果额外执行一次，只重复对应面子或留牌效果，不递归生成触发、不重复发金币。成长核心初始可贡献${base(b.growthSeed)}底分，每次合法顺子事件×${b.growthRate}。预览不成长、不入账；确认结算只提交一次。第六关和牌分×${b.summitMultiplier}。</p><h3>牌形风险</h3><p>风险提醒不预测牌山，不承诺补救成功。你可继续危险出牌；组牌时可弃换候选，也可用整趟唯一的成型弃除腾出位置，再重新填牌。满14张后的候选弃换不能直接修复成型牌。最终仍未和牌则诈胡。</p>${button('patterns','查看番型、术语与大番倍率 →','secondary')}<h3>规则适配</h3><p>使用肉鸽得分，不使用竞技符数、点棒或8番起和限制。不凭空计算门清、自摸、荣和、场风、自风及和牌张时序；术语解释和不适用原因见图鉴。纯正九莲目前未开放。国标七对允许四张相同牌拆成两对。</p><h3>保存与奖励</h3><p>V8进度独立保存，不续接V7旧局；旧版存档与成绩保留。弃换次数和改牌消耗刷新不恢复，新一关才重置。成型弃除跨关仅一次，取消确认不消耗。基础六关暂不刷新墨泉。</p>`;}

function dialogContent(){if(dialog==='patterns')return renderPatternGuide({mode,filter:guideFilter,query:guideQuery,relics:game?.mode===mode?game.relics:[]});if(dialog==='rules')return rules();if(dialog==='log')return `<h2>每次落牌，都有记录。</h2><div class="log-list">${game.log.map(x=>`<div><span>${esc(x.label||x.type||'出牌')}</span><strong>${signed(x.score??x.delta??0)}</strong><p>${esc((x.names||[]).join(' · '))}</p></div>`).join('')||'<p>本关还没有计分记录。</p>'}</div>`;
if(dialog==='formed-discard')return `<div class="section-kicker">整趟旅程 · 唯一一次</div><h2>弃除这 ${formedSelected.length} 张成型牌？</h2><div class="transform-tiles">${game.formed.filter(t=>formedSelected.includes(t.id)).map(t=>tile(t)).join('')}</div><p>选中的牌将永久弃除，不回到候选区，也不立即补摸。之后可用候选牌重新填入腾出的位置。</p><p>本次消耗整趟唯一机会${formedSelected.length===1?'，即使只弃1张也不会留下第二次':''}；下一关和刷新都不恢复。已有过程分保留，改牌次数不变。</p><div class="dialog-actions">${button('close','保留这些牌','secondary')}${button('formed-discard-confirm','确认弃除 '+formedSelected.length+' 张','primary',canDiscardFormed()?'':'disabled')}</div>`;
if(dialog==='transform'||dialog==='rescue-transform'){const rescue=dialog==='rescue-transform',t=[...game.hand,...game.formed].find(t=>t.id===chosen()[0]),numeric=t&&E.faceValue(t)<27&&!locked().has(t.id),cost=E.BALANCE.editCost;const enable=id=>editing()&&numeric&&game.ink>=cost&&(rescue?canRescue():game.relics.includes(id))?'':'disabled',tool=id=>rescue?'补缺符':`${game.relics.includes(id)?'已持有':'需要'}${E.relic(id).name}`;return `<div class="section-kicker">${rescue?'大番补缺':'改写牌面'} · 本关还可改牌 ${editsLeft()} 次 · 余 ${game.ink} 墨</div><h2>把可能，改成机会。</h2><div class="transform-tiles">${t?tile(t):''}</div><p>${rescue?'编辑消耗共用改牌额度和本关补缺机会，之后不能再用补缺弃换。':'仅准备时可改写一张候选数牌；开始组牌后，改点、换色和制作万能牌全部关闭。'}字牌与已声明杠不可改写。</p><h3>点数 ±1 · ${cost} 墨 · ${tool('rank_brush')}</h3><div class="transform-actions">${[-1,1].map(n=>button('edit',n===1?'点数 +1':'点数 −1','secondary',`data-edit="rank" data-value="${n}" data-rescue="${rescue}" ${enable('rank_brush')} ${numeric&&(E.rank(t)+n<1||E.rank(t)+n>9)?'disabled':''}`)).join('')}</div><h3>保持点数换花色 · ${cost} 墨 · ${tool('suit_ribbon')}</h3><div class="transform-actions">${['万','筒','索'].map((st,i)=>button('edit','转为'+st,'secondary',`data-edit="suit" data-value="${i}" data-rescue="${rescue}" ${enable('suit_ribbon')} ${numeric&&E.suit(t)===i&&!t.wild?'disabled':''}`)).join('')}</div>${rescue?'':`<h3>花色万能牌 · ${cost} 墨 · 大番核心专属 · ${game.relics.includes('core_high')?'已持有天机算筹':'需要天机算筹'}</h3><p>保留点数，结算时从三种数牌花色选择唯一身份；天机算筹自带，不另占槽；同样用掉本关这一次改牌。</p>${button('edit','化为三色万能牌','secondary wide',`data-edit="wild" ${enable('core_high')} ${game.wildUsed||t?.wild?'disabled':''}`)}`}`;}
if(dialog?.replaceReward){return `<h2>选一件奇物替下。</h2><p>将获得「${esc(E.relic(dialog.replaceReward).name)}」。替换后仍为4件装备，核心保持不变。</p><div class="reward-replacements">${game.relics.filter(id=>!id.startsWith('core_')).map(id=>`<button class="secondary" data-act="reward-replace" data-id="${id}">${emblem(id)}<span>替下 ${esc(E.relic(id).name)}</span></button>`).join('')}</div>${button('close','返回选择','text-btn')}`;}
if(dialog==='risk_commit')return `<h2>这一步，需要后手。</h2><p>出牌后仅靠追加牌，当前结构不能完成和牌。${repairAdvice()}</p><p>这不是“绝对无解”的判定，是否继续由你决定。</p><div class="dialog-actions">${button('close','重新选择','secondary')}${button('commit-confirm','仍然出牌','primary')}</div>`;
if(dialog==='risk_settle'){const p=E.currentSettlementPreview(game);return `<h2>${p.legal?'累计尚未达标':'确认诈胡结算？'}</h2><p>${p.legal?'本手可以和牌，但计分后仍未达到本关门槛。':`计算牌形与万能牌后仍无法和牌。本手不获和牌分，将扣除 ${fmt(p.penalty)} 分。`}</p><div class="cumulative-preview"><span>结算后累计</span><strong>${fmt(p.cumulativeAfter)}</strong><small>门槛 ${fmt(p.target)} · ${p.passed?'仍达标，可以过关':'未达标，旅程将结束'}</small></div><p>结算后本关结束，不能再修牌。</p><div class="dialog-actions">${button('close','返回调整','secondary')}${button('settle-confirm','确认结算','primary danger-btn')}</div>`;}
if(dialog==='retire')return `<h2>结束这次旅程？</h2><p>这会放弃当前挑战，保留已有累计分。</p><div class="dialog-actions">${button('close','继续组牌','secondary')}${button('retire-confirm','结束挑战','primary')}</div>`;
if(dialog==='new')return `<h2>开始新的旅程？</h2><p>当前 V8 挑战将被新进度替换；V7 及更早版本的存档仍保留。</p><div class="dialog-actions">${button('close','保留进度','secondary')}${button('start-confirm','开始新局','primary')}</div>`;
if(dialog?.relic){const row=['prepare','play'].includes(game?.phase)?buildHints(game).rows.find(x=>x.id===dialog.relic):null;return relicCard(dialog.relic)+(row?`<div class="relic-build-detail"><h3>本手构筑进度</h3>${buildHintRow(row)}</div>`:'');}return '';}
function render(){prepareBackgroundArt();document.body.classList.toggle('playing',screen==='game');const f=document.activeElement?.dataset;app.innerHTML=header()+(screen==='home'?home():game.phase==='starter'?selectionScene(true):['prepare','play'].includes(game.phase)?play():game.phase==='settlement'?settlementScene():game.phase==='reward'?selectionScene():game.phase==='shop'?shop():ending())+(dialog?`<dialog id="modal" class="modal ${dialog==='rules'?'rules-modal':''}"><div class="modal-top">${button('close','×','close-btn','aria-label="关闭弹窗"')}</div>${dialogContent()}</dialog>`:'');app.querySelectorAll('.relic-emblem img').forEach(img=>{img.addEventListener('load',()=>img.previousElementSibling.hidden=true);img.addEventListener('error',()=>img.hidden=true);if(img.complete&&img.naturalWidth)img.previousElementSibling.hidden=true;});if(dialog){const d=document.querySelector('#modal');d.showModal();d.addEventListener('cancel',e=>{e.preventDefault();dialog=null;render();});}else if(f?.act==='tile'){app.querySelector(`[data-act="tile"][data-id="${f.id}"]`)?.focus({preventScroll:true});}}
function start(){
 if(hiddenRiichiSave){
  try{let key=`${SAVE}-riichi-backup-${hiddenRiichiSave.runId}`;const existing=localStorage.getItem(key);if(existing&&existing!==hiddenRiichiSave.raw)key+=`-${Date.now()}`;localStorage.setItem(key,hiddenRiichiSave.raw);}
  catch{toast('无法备份原日麻进度，暂未开始新局，原进度仍保留。');return;}
  hiddenRiichiSave=null;
 }
 const before=capture();game=E.newRun(mode);screen='game';dialog=null;clear();track('start',before,true);persist();render();
}
function getPlayer(){return player??=createSettlementPlayer(document.querySelector('#settlement-root'));}
function controls(){wrap.querySelector('[data-act="settlement-mute"]').textContent=sound?'♪ 声音开':'♪ 声音关';wrap.querySelector('[data-act="settlement-speed"]').textContent=speed+'×';wrap.querySelector('[data-act="settlement-motion"]').textContent=reducedMotion?'完整动画':'减弱动画';}
function showSettlement(){wrap.hidden=false;app.inert=true;document.body.classList.add('settlement-open');wrap.querySelector('[data-act="settlement-continue"]').disabled=true;document.querySelector('#settlement-status').textContent='';skipped=false;controls();const before=capture();try{getPlayer().play(buildSettlementSnapshot(game,game.last),{muted:!sound,speed,reducedMotion,onComplete:({status})=>{wrap.querySelector('[data-act="settlement-continue"]').disabled=false;document.querySelector('#settlement-status').textContent=game.last.passed?(game.round===5?'累计达标，继续查看登顶结果。':'累计达标，继续领取奖励。'):'累计未达标，继续查看本次旅程。';track(status==='skipped'?'settlement_skip':'settlement_complete',before,true);}});}catch{document.querySelector('#settlement-root').innerHTML=finalSummary();wrap.querySelector('[data-act="settlement-continue"]').disabled=false;document.querySelector('#settlement-status').textContent='动画暂时不可用，计分结果已保存。';}}
function doSettle(){getPlayer().unlockAudio().catch(()=>{});const before=capture(),result=E.settle(game);track('settle',before,result);if(!result.valid){toast(result.reason);return;}dialog=null;clear();persist();render();showSettlement();}
function continueSettlement(){if(game?.phase!=='settlement')return;const before=capture();E.finishSettlement(game);track('settlement_continue',before,true);persist();wrap.hidden=true;app.inert=false;document.body.classList.remove('settlement-open');player?.dispose();player=null;render();window.scrollTo(0,0);}
function handle(e){const b=e.target.closest('[data-act]');if(!b||b.disabled)return;e.preventDefault();if(e.detail>0)inputMethod='pointer';const a=b.dataset.act;
if(a==='settlement-continue'){continueSettlement();return;}
if(a==='sound'||a==='settlement-mute'){sound=!sound;try{localStorage.setItem(PREF,String(sound));}catch{}player?.setMuted(!sound);if(sound)player?.unlockAudio().catch(()=>{});controls();render();return;}
if(a==='settlement-speed'){speed=speed===1?2:1;player?.setSpeed(speed);controls();return;}
if(a==='settlement-motion'){reducedMotion=!reducedMotion;player?.setReducedMotion(reducedMotion);controls();return;}
if(a==='settlement-skip'){skipped=true;player?.skip();return;}
if(a==='build-details'){buildExpanded=!buildExpanded;render();return;}
if(a==='patterns'){guideFilter='all';guideQuery='';dialog='patterns';render();return;}
if(a==='guide-filter'){guideFilter=b.dataset.filter;render();return;}
if(a==='rules'){dialog='rules';render();return;}
if(a==='close'){dialog=null;render();return;}
if(a==='home'){screen='home';dialog=null;render();return;}
if(a==='continue'){if(game?.mode!==mode)return;screen='game';clear();track('resume',capture(),true,{source:'save'});render();return;}
if(a==='start'){if(game&&!['victory','defeat'].includes(game.phase)){dialog='new';render();}else start();return;}
if(a==='start-confirm'){start();return;}
if(a==='restart'){start();return;}
if(!game)return;
if(a==='tile'){const before=capture(),id=b.dataset.id,zone=b.dataset.zone;let list=zone==='formed'?formedSelected:selected;list=list.includes(id)?list.filter(x=>x!==id):[...list,id];if(zone==='formed')formedSelected=list;else selected=list;track('select',before,true,{selected_tile_ids:chosen(),source_zone:zone});render();return;}
if(a==='clear'){const before=capture();clear();track('select',before,true,{selected_tile_ids:[]});render();return;}
if(a==='begin-play'){mutate('begin_play',()=>E.beginPlay(game),{},`已开始组牌，改牌已关闭；本关还可弃换候选 ${game.swaps} 次。`);return;}
if(a==='starter'){mutate('starter',()=>E.chooseStarter(game,b.dataset.id),{relic_id:b.dataset.id});return;}
if(a==='commit'){if(E.inspect(game,selected).risk==='needs_repair'){dialog='risk_commit';render();return;}}
if(a==='commit'||a==='commit-confirm'){mutate('commit',()=>E.commit(game,selected),{selected_tile_ids:[...selected],risk_confirmed:a==='commit-confirm'},r=>r.processGain?`已入成型区 · 独行印 +${fmt(r.processGain)} 分`:'已进入成型区，其余候选已保留。');return;}
if(a==='exchange'){mutate('exchange',()=>E.exchange(game,selected),{selected_tile_ids:[...selected]},'备选牌已换新。');return;}
if(a==='kong'){mutate('kong',()=>E.declareKong(game,chosen()),{selected_tile_ids:chosen()},'杠已声明并锁定，占 3 个结构位置。');return;}
if(a==='formed-discard'){if(canDiscardFormed()){dialog=a;render();}return;}
if(a==='formed-discard-confirm'){mutate('formed_discard',()=>E.discardFormed(game,[...formedSelected]),{selected_tile_ids:[...formedSelected],source_zone:'formed',count:formedSelected.length},'成型牌已弃除，本趟机会已用。请选择候选牌继续组牌。');return;}
if(a==='transform'||a==='rescue-transform'){if(preparing()&&selectedEditTile()){dialog=a;render();}return;}
if(a==='rescue-exchange'){mutate('high_rescue',()=>E.highRescue(game,{type:'exchange',ids:[...selected]}),{selected_tile_ids:[...selected],rescue_kind:'exchange'},'本关补缺机会已使用。');return;}
if(a==='edit'){const kind=b.dataset.edit,value=kind==='wild'?undefined:+b.dataset.value,rescue=b.dataset.rescue==='true';mutate(rescue?'high_rescue':'transform',()=>rescue?E.highRescue(game,{type:kind,ids:chosen(),arg:value}):E.transform(game,chosen(),kind,value),{selected_tile_ids:chosen(),transform_kind:kind,transform_value:value??null,rescue_kind:rescue?kind:undefined},'牌面已改写。');return;}
if(a==='settle'){const p=E.currentSettlementPreview(game);if(!p.valid){toast(p.reason);return;}if(!p.legal||!p.passed){dialog='risk_settle';render();return;}doSettle();return;}
if(a==='settle-confirm'){doSettle();return;}
if(a==='replay'){getPlayer().unlockAudio().catch(()=>{});showSettlement();return;}
if(a==='reward'){if(game.relics.length>=4){dialog={replaceReward:b.dataset.id};render();return;}mutate('reward',()=>E.chooseReward(game,b.dataset.id),{relic_id:b.dataset.id});return;}
if(a==='reward-replace'){const id=dialog?.replaceReward;if(id)mutate('reward',()=>E.chooseReward(game,id,b.dataset.id),{relic_id:id,replaced_relic_id:b.dataset.id});return;}
if(a==='skip-reward'){mutate('skip_reward',()=>E.skipReward(game));return;}
if(a==='next'){mutate('next_round',()=>E.nextRound(game));window.scrollTo(0,0);return;}
if(a==='log'){dialog='log';render();return;}
if(a==='relic'){dialog={relic:b.dataset.id};render();return;}
if(a==='retire'){dialog='retire';render();return;}
if(a==='retire-confirm'){mutate('retire',()=>E.retire(game));return;}}
app.addEventListener('input',e=>{if(e.target.id==='pattern-search'){guideQuery=e.target.value;document.querySelector('#pattern-results').innerHTML=renderPatternResults({mode,filter:guideFilter,query:guideQuery,relics:game?.mode===mode?game.relics:[]});}});
app.addEventListener('click',handle);wrap.addEventListener('click',handle);
document.addEventListener('keydown',e=>{inputMethod='keyboard';if(booting||e.repeat||dialog||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(!wrap.hidden){if(e.key==='Escape'){e.preventDefault();skipped=true;player?.skip();}return;}if(e.key==='Escape'){const before=capture();clear();track('select',before,true,{selected_tile_ids:[]});render();}if(e.key==='Enter'&&screen==='game'&&game?.phase==='play'&&(e.target.tagName!=='BUTTON'||e.target.dataset.act==='tile')&&e.target.tagName!=='A'){const b=app.querySelector(`[data-act="${selected.length?'commit':'settle'}"]`);if(b&&!b.disabled){e.preventDefault();b.click();}}});
async function boot(){
 app.innerHTML='<main class="art-loading"><span class="brand-tile" aria-hidden="true">雀</span><h1>正在准备牌桌</h1><p>备好牌面与起手奇物，即刻启程。</p><progress aria-label="牌面与奇物准备进度" max="1" value="0"></progress><small role="status">正在准备…</small></main>';
 let timer,ticker;
 try{
  const assets=initArtAssets();
  const update=()=>{const state=assets.getState(),progress=app.querySelector('.art-loading progress'),label=app.querySelector('.art-loading small');if(!progress)return;progress.max=state.criticalTotal||1;progress.value=state.criticalLoaded||0;if(label)label.textContent=`已准备 ${state.criticalLoaded||0} / ${state.criticalTotal||0}`;};
  update();ticker=setInterval(update,200);
  // A failed decoration request must never keep the game behind a loading page.
  await Promise.race([assets.criticalReady,new Promise(resolve=>{timer=setTimeout(resolve,8000);})]);
 }catch{}finally{clearInterval(ticker);clearTimeout(timer);booting=false;}
 applyArtStyles();
 render();
}
boot();
